CREATE OR REPLACE FUNCTION public.library_segments_range(a uuid, did uuid, ver integer, start_at integer DEFAULT 0, count_limit integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
